+const RAW_PATTERNS: &[&str] = &[
+    "ui.button(",
+    "ui.small_button(",
+    "ui.checkbox(",
+    "ui.label(",
+    "ui.add(",
+    "ui.add_enabled(",
+    "ui.add_sized(",
+    "ui.radio_value(",
+];
+
+fn count_raw_calls(src: &str) -> usize {
+    src.lines()
+        .filter(|line| !line.trim_start().starts_with("//"))
+        .map(|line| {
+            RAW_PATTERNS
+                .iter()
+                .map(|pat| line.matches(pat).count())
+                .sum::<usize>()
+        })
+        .sum()
+}
